-- FUNC08 - Assistência Social, CRAS/CREAS e benefícios. Aditiva e idempotente.
create schema if not exists sigov;

-- Complementa o cadastro legado sem conversão destrutiva.
alter table sigov.social_familia add column if not exists renda_per_capita numeric(18,2), add column if not exists territorio varchar(160);
alter table sigov.social_pessoa add column if not exists data_nascimento date, add column if not exists sexo_genero varchar(60), add column if not exists situacao_trabalho varchar(100), add column if not exists possui_deficiencia boolean not null default false, add column if not exists gestante boolean not null default false;
alter table sigov.social_atendimento add column if not exists prioridade varchar(20) not null default 'NORMAL', add column if not exists providencia text, add column if not exists resultado text, add column if not exists retorno_at timestamptz;
alter table sigov.social_visita add column if not exists agendada_at timestamptz, add column if not exists conclusao text;
alter table sigov.social_encaminhamento add column if not exists area_destino varchar(40), add column if not exists retorno text, add column if not exists concluido_at timestamptz, add column if not exists prontuario_id bigint, add column if not exists visita_id bigint;
alter table sigov.social_acompanhamento_familiar add column if not exists modalidade varchar(10) not null default 'PAIF', add column if not exists prazo date, add column if not exists motivo_encerramento text;

create table if not exists sigov.social_domicilio (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, familia_id bigint not null,
 logradouro varchar(250) not null, numero varchar(30), complemento varchar(120), bairro varchar(120) not null, cep varchar(8), municipio varchar(120) not null, uf char(2) not null,
 tipo_moradia varchar(60), situacao_moradia varchar(60), agua varchar(60), esgotamento varchar(60), territorio varchar(160), principal boolean not null default true,
 ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint,
 constraint fk_social_domicilio_familia foreign key(familia_id) references sigov.social_familia(id)
);
create table if not exists sigov.social_tecnico_referencia (
 id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, unidade_id bigint not null, usuario_id bigint not null,
 registro_profissional varchar(60), especialidade varchar(100), agenda_json jsonb not null default '{}'::jsonb, ativo boolean not null default true, is_deleted boolean not null default false,
 created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint,
 constraint fk_social_tecnico_unidade foreign key(unidade_id) references sigov.social_unidade(id), constraint fk_social_tecnico_usuario foreign key(usuario_id) references sigov.usuario(id), constraint ux_social_tecnico unique(tenant_id,entidade_id,unidade_id,usuario_id)
);
create table if not exists sigov.social_familia_tecnico (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, familia_id bigint not null, tecnico_id bigint not null, inicio date not null default current_date, fim date, ativo boolean not null default true, created_at timestamptz not null default now(), created_by bigint, constraint fk_social_ft_familia foreign key(familia_id) references sigov.social_familia(id), constraint fk_social_ft_tecnico foreign key(tecnico_id) references sigov.social_tecnico_referencia(id), constraint ck_social_ft_datas check(fim is null or fim>=inicio));
create table if not exists sigov.social_prontuario (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, familia_id bigint, social_pessoa_id bigint, numero varchar(80) not null, resumo_familiar text, demandas text, plano_acompanhamento text, status varchar(20) not null default 'ABERTO', aberto_at timestamptz not null default now(), encerrado_at timestamptz, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, constraint fk_social_pront_familia foreign key(familia_id) references sigov.social_familia(id), constraint fk_social_pront_pessoa foreign key(social_pessoa_id) references sigov.social_pessoa(id), constraint ck_social_pront_vinculo check(familia_id is not null or social_pessoa_id is not null), constraint ux_social_pront_numero unique(tenant_id,entidade_id,numero));
create table if not exists sigov.social_prontuario_evento (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, prontuario_id bigint not null, tipo varchar(40) not null, descricao text not null, dados_sensiveis jsonb not null default '{}'::jsonb, ocorrido_at timestamptz not null default now(), created_at timestamptz not null default now(), created_by bigint, constraint fk_social_pe_pront foreign key(prontuario_id) references sigov.social_prontuario(id));
create table if not exists sigov.social_beneficio_tipo (id bigint generated by default as identity primary key, tenant_id bigint not null default 0, entidade_id bigint not null default 0, codigo varchar(40) not null, nome varchar(120) not null, exige_valor boolean not null default false, integra_almoxarifado boolean not null default false, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, constraint ux_social_bt unique(tenant_id,entidade_id,codigo));
create table if not exists sigov.social_beneficio_solicitacao (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, tipo_id bigint not null, familia_id bigint, social_pessoa_id bigint, tecnico_id bigint, quantidade numeric(14,3) not null default 1, valor numeric(18,2), justificativa text not null, status varchar(20) not null default 'SOLICITADA', solicitada_at timestamptz not null default now(), analisada_at timestamptz, analisada_by bigint, decisao_justificativa text, cancelamento_justificativa text, entregue_at timestamptz, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, constraint fk_social_bs_tipo foreign key(tipo_id) references sigov.social_beneficio_tipo(id), constraint fk_social_bs_familia foreign key(familia_id) references sigov.social_familia(id), constraint fk_social_bs_pessoa foreign key(social_pessoa_id) references sigov.social_pessoa(id), constraint ck_social_bs_dest check(familia_id is not null or social_pessoa_id is not null), constraint ck_social_bs_valor check(quantidade>0 and (valor is null or valor>=0)), constraint ck_social_bs_status check(status in('SOLICITADA','EM_ANALISE','APROVADA','REPROVADA','CONCEDIDA','ENTREGUE','CANCELADA')), constraint ck_social_bs_entrega check(status<>'ENTREGUE' or (analisada_at is not null and analisada_by is not null and entregue_at is not null)));
create table if not exists sigov.social_acompanhamento_acao (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, acompanhamento_id bigint not null, descricao text not null, responsavel varchar(160) not null, prazo date, status varchar(20) not null default 'PENDENTE', evolucao text, concluida_at timestamptz, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, constraint fk_social_acao_acomp foreign key(acompanhamento_id) references sigov.social_acompanhamento_familiar(id));
create table if not exists sigov.social_scfv_grupo (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, unidade_id bigint not null, nome varchar(160) not null, faixa_etaria_inicio int not null, faixa_etaria_fim int not null, vagas int not null, atividades text, dias_horarios varchar(250), ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, constraint fk_social_scfv_unidade foreign key(unidade_id) references sigov.social_unidade(id), constraint ck_social_scfv_faixa check(faixa_etaria_inicio>=0 and faixa_etaria_fim>=faixa_etaria_inicio and vagas>0));
create table if not exists sigov.social_scfv_participante (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, grupo_id bigint not null, social_pessoa_id bigint not null, entrada date not null default current_date, desligamento date, motivo_desligamento text, ativo boolean not null default true, created_at timestamptz not null default now(), created_by bigint, constraint fk_social_scfvp_grupo foreign key(grupo_id) references sigov.social_scfv_grupo(id), constraint fk_social_scfvp_pessoa foreign key(social_pessoa_id) references sigov.social_pessoa(id), constraint ck_social_scfvp_datas check(desligamento is null or desligamento>=entrada), constraint ux_social_scfvp unique(tenant_id,entidade_id,grupo_id,social_pessoa_id));
create table if not exists sigov.social_scfv_frequencia (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, participante_id bigint not null, data_atividade date not null, presente boolean not null, atividade varchar(250) not null, observacao text, created_at timestamptz not null default now(), created_by bigint, constraint fk_social_scff_part foreign key(participante_id) references sigov.social_scfv_participante(id), constraint ux_social_scff unique(tenant_id,entidade_id,participante_id,data_atividade));
create table if not exists sigov.social_auditoria_acesso (id bigint generated by default as identity primary key, tenant_id bigint not null, entidade_id bigint not null, usuario_id bigint, acao varchar(50) not null, recurso varchar(80) not null, recurso_id bigint, finalidade varchar(250) not null, ip_hash varchar(128), dados_minimizados jsonb not null default '{}'::jsonb, ocorrido_at timestamptz not null default now());

alter table sigov.social_encaminhamento drop constraint if exists fk_social_enc_prontuario; alter table sigov.social_encaminhamento add constraint fk_social_enc_prontuario foreign key(prontuario_id) references sigov.social_prontuario(id);
alter table sigov.social_encaminhamento drop constraint if exists fk_social_enc_visita; alter table sigov.social_encaminhamento add constraint fk_social_enc_visita foreign key(visita_id) references sigov.social_visita(id);
DO $$ BEGIN IF NOT EXISTS(select 1 from pg_constraint where conname='ck_social_pessoa_renda') THEN alter table sigov.social_pessoa add constraint ck_social_pessoa_renda check(renda_individual is null or renda_individual>=0); END IF; IF NOT EXISTS(select 1 from pg_constraint where conname='ck_social_pessoa_nascimento') THEN alter table sigov.social_pessoa add constraint ck_social_pessoa_nascimento check(data_nascimento is null or data_nascimento<=current_date); END IF; END $$;
create index if not exists ix_social_domicilio_familia on sigov.social_domicilio(tenant_id,entidade_id,familia_id) where not is_deleted;
create index if not exists ix_social_tecnico_unidade on sigov.social_tecnico_referencia(tenant_id,entidade_id,unidade_id,usuario_id) where not is_deleted;
create index if not exists ix_social_prontuario_vinculo on sigov.social_prontuario(tenant_id,entidade_id,familia_id,social_pessoa_id,status) where not is_deleted;
create index if not exists ix_social_pront_evento on sigov.social_prontuario_evento(tenant_id,entidade_id,prontuario_id,ocorrido_at desc);
create index if not exists ix_social_bensol_status on sigov.social_beneficio_solicitacao(tenant_id,entidade_id,status,solicitada_at,tipo_id) where not is_deleted;
create index if not exists ix_social_visita_status_data on sigov.social_visita(tenant_id,entidade_id,status,data_visita,tecnico_usuario_id) where not is_deleted;
create index if not exists ix_social_enc_status_prazo on sigov.social_encaminhamento(tenant_id,entidade_id,status,prazo_retorno) where not is_deleted;
create index if not exists ix_social_acomp_prazo on sigov.social_acompanhamento_familiar(tenant_id,entidade_id,status,prazo) where not is_deleted;
create index if not exists ix_social_scfv_freq on sigov.social_scfv_frequencia(tenant_id,entidade_id,data_atividade,participante_id);
create index if not exists ix_social_audit_recurso on sigov.social_auditoria_acesso(tenant_id,entidade_id,recurso,recurso_id,ocorrido_at desc);

insert into sigov.social_beneficio_tipo(tenant_id,entidade_id,codigo,nome,exige_valor,integra_almoxarifado) values
(0,0,'CESTA_BASICA','Cesta básica',false,true),(0,0,'AUXILIO_FUNERAL','Auxílio funeral',true,false),(0,0,'AUXILIO_NATALIDADE','Auxílio natalidade',true,false),(0,0,'ALUGUEL_SOCIAL','Aluguel social',true,false),(0,0,'PASSAGEM','Passagem',true,false),(0,0,'DOCUMENTACAO','Documentação',true,false),(0,0,'OUTROS','Outros',false,false) on conflict(tenant_id,entidade_id,codigo) do update set nome=excluded.nome,ativo=true,is_deleted=false;
insert into sigov.permissao(modulo,chave,recurso,acao,descricao,ativo,is_deleted)
select 'social',v.chave,v.recurso,v.acao,'Permissão FUNC08 Assistência Social',true,false from(values
('SOCIAL_DASHBOARD_VIEW','social.dashboard','visualizar'),('SOCIAL_PESSOA_VIEW','social.pessoa','visualizar'),('SOCIAL_PESSOA_MANAGE','social.pessoa','gerenciar'),('SOCIAL_FAMILIA_VIEW','social.familia','visualizar'),('SOCIAL_FAMILIA_MANAGE','social.familia','gerenciar'),('SOCIAL_PRONTUARIO_VIEW','social.prontuario','visualizar'),('SOCIAL_PRONTUARIO_MANAGE','social.prontuario','gerenciar'),('SOCIAL_ATENDIMENTO_VIEW','social.atendimento','visualizar'),('SOCIAL_ATENDIMENTO_MANAGE','social.atendimento','gerenciar'),('SOCIAL_BENEFICIO_VIEW','social.beneficio','visualizar'),('SOCIAL_BENEFICIO_MANAGE','social.beneficio','gerenciar'),('SOCIAL_VISITA_VIEW','social.visita','visualizar'),('SOCIAL_VISITA_MANAGE','social.visita','gerenciar'),('SOCIAL_ENCAMINHAMENTO_VIEW','social.encaminhamento','visualizar'),('SOCIAL_ENCAMINHAMENTO_MANAGE','social.encaminhamento','gerenciar'),('SOCIAL_ACOMPANHAMENTO_VIEW','social.acompanhamento','visualizar'),('SOCIAL_ACOMPANHAMENTO_MANAGE','social.acompanhamento','gerenciar'),('SOCIAL_SCFV_VIEW','social.scfv','visualizar'),('SOCIAL_SCFV_MANAGE','social.scfv','gerenciar'),('SOCIAL_RELATORIO_EXPORT','social.relatorio','exportar'),('SOCIAL_AUDITORIA_VIEW','social.auditoria','visualizar'))v(chave,recurso,acao) where not exists(select 1 from sigov.permissao p where p.chave=v.chave);
insert into sigov.perfil_permissao(perfil_acesso_id,permissao_id,efeito,ativo,is_deleted) select pa.id,p.id,'PERMITIR',true,false from sigov.perfil_acesso pa cross join sigov.permissao p where pa.codigo_externo='SUPERADMIN' and pa.sistemico and pa.ativo and not pa.is_deleted and p.chave like 'SOCIAL_%' and p.ativo and not p.is_deleted on conflict(perfil_acesso_id,permissao_id) do update set efeito='PERMITIR',ativo=true,is_deleted=false;
